/**
 * loader.js — 초파리 뇌 데이터(manifest·색인·묶음)를 받아 신경망으로 만드는 로더.
 *
 * 워커(flybrain-worker-entry.js)에서만 쓴다. DOM 은 안 쓰지만 fetch·Cache Storage·crypto.subtle·
 * DecompressionStream 은 워커 전역 객체에 있는 것을 기본값으로 쓴다 — 전부 인자로 주입할 수 있어서
 * node 시험에서는 가짜 구현을 넣어 그대로 돌릴 수 있다(계약서 §3).
 *
 * ▣ 순서(계약서 §3, 바꾸지 말 것)
 *   1) manifest.json 을 cache:'no-cache' 로 받는다. 실패하면 Cache Storage 에 남은 사본을 쓴다.
 *   2) 색인(색인 경로는 manifest.index) — 파일명에 버전이 있으므로 **캐시 우선**(있으면 네트워크 0).
 *   3) 묶음(packs.<model>.file) — 역시 캐시 우선. 진행률 분모는 packs.<model>.size(Content-Length 는 안 믿는다).
 *   4) 새로 받은 색인·묶음은 sha256 검증을 통과해야 캐시에 넣는다. crypto.subtle 이 없으면 검증을 건너뛰고
 *      insecure:true 를 실어 보낸다.
 *   5) 15초 동안 바이트가 안 오면 중단하고 처음부터(Range 없이) 1회만 다시 받는다. 그래도 안 되면 실패.
 *      ★재시도는 중단(AbortError)·네트워크 오류일 때만 한다 — HTTP 4xx/5xx 는 다시 물어도 성공할 수
 *      없는 주소이므로 재시도하지 않는다(W9).
 *   6) 묶음은 DecompressionStream('gzip') 으로 풀고 decodePack 으로 신경망을 만든다.
 *      DecompressionStream 이 아예 없으면 {ok:false, why:'unsupported'}.
 *   7) manifest 도 색인·묶음과 같은 스톨 가드를 통과한다(W3) — 응답 없는 네트워크에서 loadModel 이
 *      영원히 안 끝나는 것을 막는다. 실패하면(스톨·HTTP 오류 모두) 캐시에 남은 manifest 로 진행한다.
 *   8) opts.deadlineMs 를 주면 색인/묶음 시작 전·풀기 전에 남은 시간을 확인해 넘겼으면
 *      {ok:false, why:'timeout'} 으로 즉시 끝낸다(W5 — 워커가 항상 메인의 60초 타임아웃보다 먼저 답하게).
 *
 * loadModel 은 절대 밖으로 던지지 않는다 — 무엇이 잘못되든 {ok:false, why, detail} 로 끝난다.
 */
'use strict';

const {decodePack} = require('./lif-core');

const CACHE_NAME = 'flybrain-v1';
const STALL_MS = 15000;
const SHA256_RE = /^[0-9a-f]{64}$/i;
const NUMERIC_PARAMS = ['v0', 'vReset', 'vTh', 'wSyn', 'wIn', 'eM', 'eS', 'kGV', 'delaySteps', 'refSteps', 'dtMs'];

/**
 * base 주소에 상대경로를 붙인다. base 에 끝 슬래시가 없어도 마지막 구획이 안 잘리게 보정한다.
 * @param {string} base 뇌 데이터 폴더 주소(끝 슬래시 있어도 없어도 됨)
 * @param {string} rel manifest.json 같은 상대경로
 * @returns {string} 완성된 절대 URL 문자열
 */
const resolveUrl = function (base, rel) {
    const b = (base && base.endsWith('/')) ? base : `${base}/`;
    return new URL(rel, b).toString();
};

/**
 * manifest.json 의 모양을 검사한다.
 * @param {*} obj JSON.parse 한 manifest
 * @returns {{ok: boolean, why: (string|undefined)}} 통과 여부
 */
const validateManifest = function (obj) {
    if (!obj || typeof obj !== 'object') return {ok: false, why: 'manifest:not-object'};
    if (obj.format !== 1) return {ok: false, why: 'manifest:bad-format'};
    if (typeof obj.index !== 'string' || obj.index.length === 0) return {ok: false, why: 'manifest:bad-index'};
    if (typeof obj.indexSha256 !== 'undefined' && !SHA256_RE.test(obj.indexSha256)) {
        return {ok: false, why: 'manifest:bad-indexSha256'};
    }
    if (typeof obj.mirrors !== 'undefined' && !Array.isArray(obj.mirrors)) {
        return {ok: false, why: 'manifest:bad-mirrors'};
    }
    return {ok: true};
};

/**
 * 색인(index-N.json) 이 지정한 모델(pack)을 실제로 다룰 수 있는 모양인지 검사한다.
 * @param {*} obj JSON.parse 한 색인
 * @param {string} modelKey 예: 'reflex'
 * @returns {{ok: boolean, why: (string|undefined)}} 통과 여부
 */
const validateIndex = function (obj, modelKey) {
    if (!obj || typeof obj !== 'object') return {ok: false, why: 'index:not-object'};
    if (obj.format !== 1) return {ok: false, why: 'index:bad-format'};
    if (!obj.params || typeof obj.params !== 'object') return {ok: false, why: 'index:missing-params'};
    for (let i = 0; i < NUMERIC_PARAMS.length; i++) {
        const key = NUMERIC_PARAMS[i];
        if (typeof obj.params[key] !== 'number' || !isFinite(obj.params[key])) {
            return {ok: false, why: `index:bad-param-${key}`};
        }
    }
    if (!obj.packs || typeof obj.packs !== 'object') return {ok: false, why: 'index:missing-packs'};
    const pack = obj.packs[modelKey];
    if (!pack || typeof pack !== 'object') return {ok: false, why: 'index:unknown-model'};
    if (typeof pack.file !== 'string' || pack.file.length === 0) return {ok: false, why: 'index:bad-pack-file'};
    if (typeof pack.size !== 'number' || pack.size <= 0) return {ok: false, why: 'index:bad-pack-size'};
    if (typeof pack.sha256 !== 'string' || !SHA256_RE.test(pack.sha256)) {
        return {ok: false, why: 'index:bad-pack-sha256'};
    }
    if (typeof pack.n !== 'number' || pack.n <= 0) return {ok: false, why: 'index:bad-pack-n'};
    if (!Array.isArray(pack.groups) || !Array.isArray(pack.inputs) || !Array.isArray(pack.outputs)) {
        return {ok: false, why: 'index:bad-pack-lists'};
    }
    if (!obj.groups || typeof obj.groups !== 'object') return {ok: false, why: 'index:missing-groups'};
    if (!obj.inputs || typeof obj.inputs !== 'object') return {ok: false, why: 'index:missing-inputs'};
    if (!obj.outputs || typeof obj.outputs !== 'object') return {ok: false, why: 'index:missing-outputs'};
    for (let i = 0; i < pack.groups.length; i++) {
        const g = pack.groups[i];
        if (!obj.groups[g] || !Array.isArray(obj.groups[g].gids)) return {ok: false, why: `index:missing-group-${g}`};
    }

    // parts·neg 가 가리키는 집단은 index.groups 에 정의돼 있어야 하고, 이 모델(pack)의 groups 목록에도
    // 있어야 한다(둘 중 하나만 어겨도 같은 오류) — mapGroupsToLocal 은 pack.groups 로만 groups{} 를
    // 채우므로, 여기서 걸러 두지 않으면 나중에 조용히 빈 Int32Array(0)로 떨어진다(2단계 계약서 §2-1).
    const groupUsableInPack = function (g) {
        return typeof g === 'string' && pack.groups.indexOf(g) !== -1 &&
            !!obj.groups[g] && Array.isArray(obj.groups[g].gids);
    };

    // 묶음 안의 모든 입력이 지금까지 가리킨 집단(1판 group 필드·2판 parts[].group 전부 포함) — 서로
    // 다른 입력이 같은 뉴런 집단을 가리키면 같은 자극이 두 번 더해져 기준 시뮬레이터와 어긋난다(심사 C2).
    const usedInputGroups = new Set();
    const claimInputGroup = function (g) {
        if (usedInputGroups.has(g)) return false;
        usedInputGroups.add(g);
        return true;
    };

    for (let i = 0; i < pack.inputs.length; i++) {
        const k = pack.inputs[i];
        const def = obj.inputs[k];
        if (!def || typeof def.group !== 'string' || typeof def.maxRateHz !== 'number') {
            return {ok: false, why: `index:bad-input-${k}`};
        }
        // parts(2판, 선택) — 있으면 배열(길이 1 이상)이고 원소마다 group(문자열)·maxRateHz(유한한 양수)여야
        // 한다. 없는 1판 정의는 group 필드 하나만 쓴다(mapGroupsToLocal 이 나중에 원소 1개짜리로 채워 준다).
        if (typeof def.parts !== 'undefined') {
            if (!Array.isArray(def.parts) || def.parts.length === 0) return {ok: false, why: `index:bad-input-${k}`};
            const seenInThisInput = new Set(); // 한 입력 안에서 같은 집단을 두 parts 가 가리키면 안 된다
            for (let j = 0; j < def.parts.length; j++) {
                const part = def.parts[j];
                if (!part || typeof part.group !== 'string' ||
                    typeof part.maxRateHz !== 'number' || !isFinite(part.maxRateHz) || part.maxRateHz <= 0) {
                    return {ok: false, why: `index:bad-input-${k}`};
                }
                if (!groupUsableInPack(part.group)) return {ok: false, why: `index:missing-group-${part.group}`};
                if (seenInThisInput.has(part.group)) return {ok: false, why: `index:bad-input-${k}`};
                seenInThisInput.add(part.group);
                if (!claimInputGroup(part.group)) return {ok: false, why: `index:bad-input-${k}`};
            }
        } else if (!claimInputGroup(def.group)) {
            return {ok: false, why: `index:bad-input-${k}`};
        }
    }
    for (let i = 0; i < pack.outputs.length; i++) {
        const k = pack.outputs[i];
        const def = obj.outputs[k];
        if (!def || !Array.isArray(def.groups) || def.groups.length === 0 ||
            typeof def.fullHz !== 'number' || !isFinite(def.fullHz) || def.fullHz <= 0 ||
            typeof def.on !== 'number' || !isFinite(def.on) ||
            typeof def.off !== 'number' || !isFinite(def.off) ||
            typeof def.smoothMs !== 'number' || !isFinite(def.smoothMs)) {
            return {ok: false, why: `index:bad-output-${k}`};
        }
        for (let j = 0; j < def.groups.length; j++) {
            if (!groupUsableInPack(def.groups[j])) return {ok: false, why: `index:missing-group-${def.groups[j]}`};
        }
        // neg(2판, 선택) — 있으면 문자열 배열이어야 한다. kind:'signed' 인데 neg 가 없거나 비어 있으면
        // 부호를 계산할 반대쪽이 없다는 뜻이라 같은 오류로 거부한다.
        if (typeof def.neg !== 'undefined') {
            if (!Array.isArray(def.neg)) return {ok: false, why: `index:bad-output-${k}`};
            for (let j = 0; j < def.neg.length; j++) {
                if (typeof def.neg[j] !== 'string') return {ok: false, why: `index:bad-output-${k}`};
            }
        }
        if (def.kind === 'signed' && (!Array.isArray(def.neg) || def.neg.length === 0)) {
            return {ok: false, why: `index:bad-output-${k}`};
        }
        if (Array.isArray(def.neg)) {
            for (let j = 0; j < def.neg.length; j++) {
                if (!groupUsableInPack(def.neg[j])) return {ok: false, why: `index:missing-group-${def.neg[j]}`};
            }
            // groups 와 neg 가 겹치면(같은 집단을 양쪽에 걸면) 부호 계산이 스스로를 상쇄한다 - 거부.
            for (let j = 0; j < def.groups.length; j++) {
                if (def.neg.indexOf(def.groups[j]) !== -1) return {ok: false, why: `index:bad-output-${k}`};
            }
        }
    }
    return {ok: true};
};

/**
 * 색인의 전역 뉴런 번호(gids)를 묶음 안 번호(gidArray 의 자리)로 바꾼다.
 * 묶음에 없는 전역 번호는 버린다(계약서 §3 — "묶음에 없는 전역 번호는 버린다").
 * @param {object} index 색인(index-N.json 을 JSON.parse 한 것)
 * @param {string} packKey 예: 'reflex' — index.packs[packKey] 가 이 묶음이 다루는 집단·입력·출력 키 목록을 준다
 * @param {Uint32Array} gidArray 묶음의 gid[](묶음 안 번호 → 전역 번호)
 * @returns {{
 *   groups: Object<string, Int32Array>,
 *   inputs: Object<string, {idx: Int32Array, maxRateHz: number, parts: Array<{idx: Int32Array, maxRateHz: number}>}>,
 *   outputs: Object<string, {idxList: Array<Int32Array>, n: number, fullHz: number, on: number, off: number, smoothMs: number, kind: string, negIdxList: Array<Int32Array>, negN: number}>
 * }} 묶음 안 번호로 바뀐 집단·입력·출력. `parts` 가 없는 1판 입력 정의는 원소 1개짜리로 채워 준다
 *   (idx·maxRateHz 는 그대로 두고 = parts[0]). `neg` 가 없는 출력은 negIdxList 빈 배열·negN 0.
 */
const mapGroupsToLocal = function (index, packKey, gidArray) {
    const pack = (index.packs && index.packs[packKey]) || null;

    const globalToLocal = new Map();
    for (let i = 0; i < gidArray.length; i++) globalToLocal.set(gidArray[i], i);

    const groups = {};
    const groupKeys = (pack && pack.groups) || Object.keys(index.groups || {});
    for (let i = 0; i < groupKeys.length; i++) {
        const key = groupKeys[i];
        const def = index.groups && index.groups[key];
        if (!def) continue;
        const local = [];
        for (let j = 0; j < def.gids.length; j++) {
            const li = globalToLocal.get(def.gids[j]);
            if (typeof li !== 'undefined') local.push(li);
        }
        groups[key] = Int32Array.from(local);
    }

    const inputs = {};
    const inputKeys = (pack && pack.inputs) || Object.keys(index.inputs || {});
    for (let i = 0; i < inputKeys.length; i++) {
        const key = inputKeys[i];
        const def = index.inputs && index.inputs[key];
        if (!def) continue;
        const idx = groups[def.group] || new Int32Array(0);
        // parts(2판) — 집단마다 다른 최대 발화율로 자극할 수 있도록 묶음 안 번호로 미리 바꿔 둔다.
        // parts 가 없는 1판 정의는 지금까지의 idx·maxRateHz 를 그대로 원소 1개로 채운다(하위 호환).
        const parts = Array.isArray(def.parts)
            ? def.parts.map(part => ({idx: groups[part.group] || new Int32Array(0), maxRateHz: part.maxRateHz}))
            : [{idx, maxRateHz: def.maxRateHz}];
        inputs[key] = {idx, maxRateHz: def.maxRateHz, parts};
    }

    const outputs = {};
    const outputKeys = (pack && pack.outputs) || Object.keys(index.outputs || {});
    for (let i = 0; i < outputKeys.length; i++) {
        const key = outputKeys[i];
        const def = index.outputs && index.outputs[key];
        if (!def) continue;
        const idxList = [];
        let n = 0;
        for (let j = 0; j < def.groups.length; j++) {
            const idx = groups[def.groups[j]] || new Int32Array(0);
            idxList.push(idx);
            n += idx.length;
        }
        // neg(2판, 부호형 출력의 반대쪽 집단) — 없으면 빈 배열·0(세기형 출력은 이 상태 그대로 쓴다).
        const negIdxList = [];
        let negN = 0;
        if (Array.isArray(def.neg)) {
            for (let j = 0; j < def.neg.length; j++) {
                const idx = groups[def.neg[j]] || new Int32Array(0);
                negIdxList.push(idx);
                negN += idx.length;
            }
        }
        outputs[key] = {
            idxList,
            n,
            fullHz: def.fullHz,
            on: def.on,
            off: def.off,
            smoothMs: def.smoothMs,
            kind: def.kind,
            negIdxList,
            negN
        };
    }

    return {groups, inputs, outputs};
};

/**
 * ArrayBuffer 의 sha256 을 16진 소문자 문자열로. crypto.subtle 이 없으면 null(호출부가 insecure 로 처리).
 * @param {ArrayBuffer} buf 대상 바이트
 * @param {Crypto=} cryptoImpl 주입용(기본은 전역 crypto)
 * @returns {Promise<string|null>} 64자 16진 해시 또는 null
 */
const sha256Hex = async function (buf, cryptoImpl) {
    // 둘째 인자를 아예 안 줬을 때만 전역 crypto 로 대체한다 — 호출부가 명시적으로 null 을 줬다면
    // (예: crypto.subtle 없는 상황을 흉내 낸 시험) 그 뜻을 그대로 존중해 null 을 돌려준다.
    const c = (arguments.length >= 2) ? cryptoImpl : (typeof crypto !== 'undefined' ? crypto : null);
    if (!c || !c.subtle) return null;
    const digest = await c.subtle.digest('SHA-256', buf);
    const bytes = new Uint8Array(digest);
    let hex = '';
    for (let i = 0; i < bytes.length; i++) hex += bytes[i].toString(16).padStart(2, '0');
    return hex;
};

/** ArrayBuffer(UTF-8) 를 문자열로. */
const _bufToText = function (buf) {
    if (typeof TextDecoder !== 'undefined') return new TextDecoder('utf-8').decode(buf);
    return Buffer.from(buf).toString('utf-8'); // node 아주 옛 버전 대비 — 사실상 안 탄다
};

/** Cache Storage 를 열되 실패해도(사생활 보호 모드 등) null 로 넘어간다. */
const _openCacheSafe = async function (cachesImpl) {
    try {
        return await cachesImpl.open(CACHE_NAME);
    } catch (e) {
        return null;
    }
};

/** 응답 본문을 스트리밍으로 읽으며 도착할 때마다 onChunk(청크, 지금까지 누적 바이트) 를 부른다. */
const _readStream = async function (response, onChunk) {
    if (!response.body || typeof response.body.getReader !== 'function') {
        const buf = await response.arrayBuffer();
        if (onChunk) onChunk(new Uint8Array(buf), buf.byteLength);
        return buf;
    }
    const reader = response.body.getReader();
    const chunks = [];
    let total = 0;
    for (;;) {
        // eslint-disable-next-line no-await-in-loop
        const {done, value} = await reader.read();
        if (done) break;
        if (value && value.length) {
            chunks.push(value);
            total += value.length;
            if (onChunk) onChunk(value, total);
        }
    }
    const out = new Uint8Array(total);
    let off = 0;
    for (let i = 0; i < chunks.length; i++) {
        out.set(chunks[i], off);
        off += chunks[i].length;
    }
    return out.buffer;
};

/**
 * 한 번 받기 시도 — 15초 동안 새 바이트가 없으면 스스로 중단한다(AbortController).
 * @param {Function} fetchImpl 주입된 fetch
 * @param {string} url
 * @param {Function=} onProgress (loaded) => void
 * @param {object=} extraOpts fetch 에 함께 넘길 옵션(예: {cache:'no-cache'}, manifest 전용 — W3)
 * @returns {Promise<ArrayBuffer>} 받은 바이트(실패하면 던진다 — 바깥에서 잡는다)
 */
const _fetchAttempt = function (fetchImpl, url, onProgress, extraOpts) {
    const controller = (typeof AbortController !== 'undefined') ? new AbortController() : null;
    let timer = null;
    let settled = false;
    const armStall = function () {
        if (!controller) return;
        if (timer) clearTimeout(timer);
        timer = setTimeout(() => {
            if (!settled) controller.abort();
        }, STALL_MS);
    };
    armStall();
    const opts = Object.assign({}, extraOpts || {}, controller ? {signal: controller.signal} : {});
    return fetchImpl(url, opts)
        .then(res => {
            if (!res || !res.ok) {
                // 메시지 접두 'http-' 로 "재시도해도 소용없는 HTTP 오류"를 구분한다(W9 재시도 조건).
                const err = new Error(`http-${res && res.status}`);
                throw err;
            }
            return _readStream(res, (chunk, loaded) => {
                armStall();
                if (onProgress) onProgress(loaded);
            });
        })
        .then(buf => {
            settled = true;
            if (timer) clearTimeout(timer);
            return buf;
        })
        .catch(e => {
            settled = true;
            if (timer) clearTimeout(timer);
            throw e;
        });
};

/**
 * 스톨 가드 + 1회 재시도가 적용된 받기. 실패해도 던지지 않고 {ok:false, why, detail} 을 돌려준다.
 * ★재시도(2번째 시도)는 중단(AbortError)이거나 네트워크 오류일 때만 한다 — HTTP 4xx/5xx 는 다시
 * 물어도 성공할 수 없는 주소이므로 그 자리에서 포기한다(W9). 시도를 시작할 때마다 onProgress(0, total)
 * 을 한 번 불러 재시도가 "되감기"처럼 보이지 않게 한다(전 시도의 진행률이 남아 있다는 오해를 막는다).
 * @param {Function} fetchImpl 주입된 fetch
 * @param {string} url 받을 주소
 * @param {Function=} onProgress (loaded, total) => void — total 은 호출부가 넘긴 고정값(색인은 안 씀)
 * @param {number=} total 진행률 분모(묶음만 의미 있음, §3 — Content-Length 를 믿지 않는다)
 * @param {object=} extraOpts fetch 에 함께 넘길 옵션(manifest 의 {cache:'no-cache'} 등 — W3)
 * @returns {Promise<{ok: boolean, buffer: (ArrayBuffer|undefined), why: (string|undefined), detail: *}>}
 */
const _fetchWithStallGuard = async function (fetchImpl, url, onProgress, total, extraOpts) {
    let lastErr = null;
    for (let attempt = 0; attempt < 2; attempt++) {
        try {
            if (onProgress) onProgress(0, total);
            // eslint-disable-next-line no-await-in-loop
            const buf = await _fetchAttempt(fetchImpl, url, loaded => {
                if (onProgress) onProgress(loaded, total);
            }, extraOpts);
            return {ok: true, buffer: buf};
        } catch (e) {
            lastErr = e;
            const isAbort = e && e.name === 'AbortError';
            const isHttpError = e && typeof e.message === 'string' && e.message.indexOf('http-') === 0;
            if (!isAbort && isHttpError) break; // HTTP 4xx/5xx — 재시도하지 않는다(W9)
        }
    }
    return {ok: false, why: 'download-failed', detail: (lastErr && lastErr.message) || String(lastErr)};
};

/** buf(gzip) 를 DecompressionStream 으로 풀어 ArrayBuffer 로. */
const _gunzip = async function (buf, DecompressionStreamImpl) {
    const ds = new DecompressionStreamImpl('gzip');
    const source = new Response(buf).body.pipeThrough(ds);
    return new Response(source).arrayBuffer();
};

/**
 * 초파리 뇌 모델을 받아 신경망으로 만든다. 절대 밖으로 던지지 않는다.
 * @param {object} opts
 * @param {string} opts.base 뇌 데이터 폴더 주소
 * @param {string} opts.model 예: 'reflex'
 * @param {Function=} opts.onProgress (loaded, total) => void — 묶음 다운로드 중에만 부른다
 * @param {Function=} opts.fetchImpl 기본은 전역 fetch
 * @param {CacheStorage=} opts.cachesImpl 기본은 전역 caches(없으면 캐시 없이 진행)
 * @param {Crypto=} opts.cryptoImpl 기본은 전역 crypto
 * @param {Function=} opts.DecompressionStreamImpl 기본은 전역 DecompressionStream
 * @param {number=} opts.deadlineMs 전체 적재 마감(W5) — 색인/묶음 시작 전·풀기 전에 남은 시간을 확인해
 *   넘겼으면 {ok:false, why:'timeout'} 으로 즉시 끝낸다. 안 주면 무제한(기존 동작 그대로).
 * @param {Function=} opts.now 시각 함수(시험 주입용). 기본은 Date.now.
 * @returns {Promise<object>} {ok:true, index, manifest, packKey, net, groups, inputs, outputs, insecure} 또는 {ok:false, why, detail}
 */
// opts 에 키가 아예 없을 때만 전역 기본값을 쓴다. `{fetchImpl: null}` 처럼 **명시적으로 null 을 준 경우는
// "이 기능 없음"으로 그대로 존중한다** — 그래야 시험이 "crypto.subtle 없음"·"DecompressionStream 없음" 같은
// 상황을 실제 브라우저 없이도 흉내 낼 수 있다(`opts.X || 기본값` 이었다면 null 이 다시 전역값으로 되돌아가
// 이 실패 경로 자체를 시험할 수 없었다).
const _pick = function (opts, key, fallback) {
    return Object.prototype.hasOwnProperty.call(opts, key) ? opts[key] : fallback;
};

const loadModel = async function (opts) {
    opts = opts || {};
    const base = opts.base;
    const model = opts.model;
    const onProgress = opts.onProgress || function () { /* no-op */ };
    const fetchImpl = _pick(opts, 'fetchImpl', typeof fetch !== 'undefined' ? fetch : null);
    const cachesImpl = _pick(opts, 'cachesImpl', typeof caches !== 'undefined' ? caches : null);
    const cryptoImpl = _pick(opts, 'cryptoImpl', typeof crypto !== 'undefined' ? crypto : null);
    const DecompressionStreamImpl = _pick(
        opts, 'DecompressionStreamImpl', typeof DecompressionStream !== 'undefined' ? DecompressionStream : null
    );

    try {
        if (!fetchImpl) return {ok: false, why: 'no-fetch'};
        if (!DecompressionStreamImpl) return {ok: false, why: 'unsupported'};
        if (!base || !model) return {ok: false, why: 'bad-args'};

        const cache = cachesImpl ? await _openCacheSafe(cachesImpl) : null;
        let insecure = false;

        // 0) 전체 마감(W5) — opts.now 로 시각을 주입할 수 있다(시험용). deadlineMs 를 안 주면 무제한.
        const nowImpl = (typeof opts.now === 'function') ? opts.now : Date.now;
        const deadlineAt = (typeof opts.deadlineMs === 'number') ? (nowImpl() + opts.deadlineMs) : null;
        const _timedOut = function () {
            return deadlineAt !== null && nowImpl() >= deadlineAt;
        };

        // 1) manifest — 항상 네트워크 우선(같은 스톨 가드를 통과 — W3), 실패하면 캐시 사본
        const manifestUrl = resolveUrl(base, 'manifest.json');
        let manifest = null;
        const manifestDl = await _fetchWithStallGuard(fetchImpl, manifestUrl, null, 0, {cache: 'no-cache'});
        if (manifestDl.ok) {
            try {
                const text = _bufToText(manifestDl.buffer);
                const parsed = JSON.parse(text);
                const v = validateManifest(parsed);
                if (!v.ok) throw new Error(v.why);
                manifest = parsed;
                if (cache) {
                    try {
                        await cache.put(manifestUrl, new Response(text, {headers: {'content-type': 'application/json'}}));
                    } catch (e) { /* 캐시 저장 실패는 무시 — 못 받아도 이번 로드는 이어간다 */ }
                }
            } catch (e) {
                manifest = null; // 파싱·검증 실패도 아래에서 캐시 사본으로 넘어간다
            }
        }
        if (!manifest) {
            // 스톨·중단·HTTP 오류·파싱 실패 — 뭐든 실패하면 캐시에 남은 manifest 로 진행한다(§3).
            if (cache) {
                const cached = await cache.match(manifestUrl);
                if (cached) {
                    try {
                        manifest = JSON.parse(await cached.text());
                    } catch (e2) { /* 캐시도 못 읽으면 아래에서 실패 처리 */ }
                }
            }
            if (!manifest) {
                return {
                    ok: false, why: 'manifest-failed',
                    detail: (manifestDl && manifestDl.detail) || 'manifest-unavailable'
                };
            }
        }

        // 2) 색인 — 파일명에 버전이 있으니 캐시 우선
        if (_timedOut()) return {ok: false, why: 'timeout'};
        const indexUrl = resolveUrl(base, manifest.index);
        let indexBuf = null;
        if (cache) {
            const cached = await cache.match(indexUrl);
            if (cached) indexBuf = await cached.arrayBuffer();
        }
        if (!indexBuf) {
            const dl = await _fetchWithStallGuard(fetchImpl, indexUrl, null, 0);
            if (!dl.ok) return dl;
            indexBuf = dl.buffer;
            if (manifest.indexSha256) {
                const hex = await sha256Hex(indexBuf, cryptoImpl);
                if (hex === null) {
                    insecure = true;
                } else if (hex !== manifest.indexSha256) {
                    return {ok: false, why: 'sha-mismatch', detail: 'index'};
                }
            } else {
                insecure = insecure || !(cryptoImpl && cryptoImpl.subtle);
            }
            if (cache) {
                try {
                    await cache.put(indexUrl, new Response(indexBuf.slice(0)));
                } catch (e) { /* 캐시 저장 실패 무시 */ }
            }
        }
        const index = JSON.parse(_bufToText(indexBuf));
        const iv = validateIndex(index, model);
        if (!iv.ok) return {ok: false, why: 'index-invalid', detail: iv.why};

        const packInfo = index.packs[model];

        // 3) 묶음 — 캐시 우선, 진행률 분모는 packInfo.size
        if (_timedOut()) return {ok: false, why: 'timeout'};
        const packUrl = resolveUrl(base, packInfo.file);
        let packGz = null;
        let packFromCache = false;
        if (cache) {
            const cached = await cache.match(packUrl);
            if (cached) {
                packGz = await cached.arrayBuffer();
                packFromCache = true;
            }
        }
        if (packFromCache) {
            onProgress(packInfo.size, packInfo.size);
        } else {
            const dl = await _fetchWithStallGuard(fetchImpl, packUrl, onProgress, packInfo.size);
            if (!dl.ok) return dl;
            packGz = dl.buffer;
            const hex = await sha256Hex(packGz, cryptoImpl);
            if (hex === null) {
                insecure = true;
            } else if (hex !== packInfo.sha256) {
                return {ok: false, why: 'sha-mismatch', detail: 'pack'};
            }
            if (cache) {
                try {
                    await cache.put(packUrl, new Response(packGz.slice(0)));
                } catch (e) { /* 캐시 저장 실패 무시 */ }
            }
        }

        // 4) 풀기 + 디코드
        if (_timedOut()) return {ok: false, why: 'timeout'};
        let packBuf;
        try {
            packBuf = await _gunzip(packGz, DecompressionStreamImpl);
        } catch (e) {
            return {ok: false, why: 'gunzip-failed', detail: (e && e.message) || String(e)};
        }
        let net;
        try {
            net = decodePack(packBuf);
        } catch (e) {
            return {ok: false, why: 'decode-failed', detail: (e && e.message) || String(e)};
        }

        const mapped = mapGroupsToLocal(index, model, net.gid);

        return {
            ok: true,
            index,
            manifest,
            packKey: model,
            net,
            groups: mapped.groups,
            inputs: mapped.inputs,
            outputs: mapped.outputs,
            insecure
        };
    } catch (e) {
        return {ok: false, why: 'internal-error', detail: (e && e.message) || String(e)};
    }
};

module.exports = {
    resolveUrl,
    validateManifest,
    validateIndex,
    mapGroupsToLocal,
    sha256Hex,
    loadModel
};
