/**
 * lif-core.js — 초파리 전뇌 실험실(flybrain)의 신경망 계산 코어.
 *
 * DOM·워커·fetch 의존이 없는 순수 모듈이다. 워커(flybrain-worker-entry.js)와 node 단위 시험이 같은 파일을 쓴다.
 *
 * ▣ 되돌리면 안 되는 것 — 1스텝의 순서 (Brian2 원본과 전뇌 스파이크 전수 일치로 확정, 2026-09-21)
 *   기준은 Python 기준 시뮬레이터 `_tools_flybrain/fb_common.py` 의 RefSim 이고, 이 파일은 그것과 **비트 단위로 같은 결과**를 내야 한다
 *   (시험: test/unit/flybrain_lif_core.js — 미리 만든 입력 스파이크열에 대해 모든 스파이크의 (뉴런, 스텝) 이 일치).
 *     (a) 불응 중이 아닌 뉴런만 v, g 를 닫힌 해로 한 스텝 전진 (불응 중에는 둘 다 동결)
 *     (b) 문턱: v > vTh (등호 없음) 이고 불응 중이 아님 → 발화
 *     (c) 시냅스: delaySteps 전에 발화한 뉴런의 행을 훑어 g += w. ★불응 중인 뉴런에 온 도착분은 버린다(Brian2 조건부 쓰기)
 *         입력 스파이크 v += wIn 도 같은 규칙. 불응 여부는 (a)에서 계산한 값을 쓴다(이번 스텝에 발화한 뉴런은 아직 "불응 아님").
 *     (d) 리셋: 이번 스텝에 발화한 뉴런 v = vReset, g = 0 (같은 스텝에 받은 도착분도 같이 지워진다)
 *   - 도착 뉴런은 번호 오름차순으로 처리한다. g 에 더하는 순서가 바뀌면 부동소수 합이 달라져 비트 일치가 깨진다.
 *   - 감쇠 상수(eM, eS, kGV)는 Math.exp 로 다시 계산하지 않고 **묶음 파일에 실린 값**을 쓴다(Math.exp 와 numpy.exp 의 마지막 비트 차이 방지).
 *   - 갱신식의 연산 순서를 바꾸지 말 것: v0 + (v - v0) * eM + g * kGV
 *   - 자극 중인 입력 뉴런은 불응기 0(원본 model.py 의 rfc = 0). 자극을 끄면 원래 불응기로 돌아간다.
 *   - 끄기(silence) = 그 뉴런의 발화를 전파하지 않음(원본은 나가는 연결 가중치 0 — 하류 효과가 같다). 꺼진 뉴런의 활동은 0 으로 센다.
 */

/**
 * 시드 고정 난수(mulberry32). 같은 씨앗·같은 입력열이면 같은 결과.
 * @param {number} seed 32비트 정수
 * @returns {function(): number} [0, 1) 난수
 */
const mulberry32 = function (seed) {
    let a = seed >>> 0;
    return function () {
        a = (a + 0x6D2B79F5) >>> 0;
        let t = a;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
};

class LifCore {
    /**
     * @param {object} net 묶음에서 풀어낸 신경망
     * @param {number} net.n 뉴런 수(묶음 안 번호 0..n-1)
     * @param {Uint32Array} net.rowptr 행 시작 위치(길이 n+1) — 행 = 전시냅스 뉴런
     * @param {Uint32Array} net.col 후시냅스 번호(행 안에서 오름차순)
     * @param {Float64Array} net.wv 연결 가중치(볼트) = 부호 있는 시냅스 수 × wSyn
     * @param {object} net.params {v0, vReset, vTh, eM, eS, kGV, wIn, delaySteps, refSteps, dtMs}
     */
    constructor (net) {
        this.n = net.n;
        this.rowptr = net.rowptr;
        this.col = net.col;
        this.wv = net.wv;
        this.p = net.params;
        const n = this.n;
        this.v = new Float64Array(n);
        this.g = new Float64Array(n);
        this.last = new Int32Array(n);          // 마지막 발화 스텝
        this.rfc = new Int32Array(n);           // 뉴런별 불응 스텝(자극 중인 입력 뉴런은 0)
        this.nr = new Uint8Array(n);            // 이번 스텝의 "불응 아님" 표시
        this.silenced = new Uint8Array(n);
        this.spikeCount = new Uint32Array(n);   // 디코더가 읽고 비우는 누적 발화 수
        this.ring = [];
        for (let i = 0; i <= this.p.delaySteps; i++) this.ring.push(new Int32Array(0));
        this.inputs = [];                       // [{idx: Int32Array, pStep: number}] — 자극 중인 집단
        this.rand = mulberry32(1);
        this.k = 0;
        this.onSpike = null;                    // 시험용: (뉴런, 스텝) 콜백
        this.reset(1);
    }

    /**
     * 막전위·시냅스·발화 기록·시뮬레이션 시간을 처음으로. 끄기·자극 설정은 건드리지 않는다.
     * @param {number} seed 난수 씨앗
     */
    reset (seed) {
        const p = this.p;
        this.v.fill(p.v0);
        this.g.fill(0);
        this.last.fill(-1000000000);
        this.spikeCount.fill(0);
        for (let i = 0; i < this.ring.length; i++) this.ring[i] = new Int32Array(0);
        this.k = 0;
        this.rand = mulberry32(seed);
    }

    /**
     * 자극 집단을 통째로 다시 정한다. 세기가 0 인 집단은 넣지 않는다(그 뉴런은 보통 뉴런으로 돌아간다).
     * @param {Array<{idx: Int32Array, rateHz: number}>} list 자극 목록
     */
    setInputs (list) {
        this.rfc.fill(this.p.refSteps);
        this.inputs = [];
        for (const it of list) {
            if (!(it.rateHz > 0)) continue;
            for (let j = 0; j < it.idx.length; j++) this.rfc[it.idx[j]] = 0;
            this.inputs.push({idx: it.idx, pStep: it.rateHz * this.p.dtMs / 1000});
        }
    }

    /**
     * 한 스텝 전진.
     * @param {Int32Array=} forcedIn 시험용 — 이번 스텝에 입력 스파이크를 받을 뉴런 번호(주면 난수 입력을 쓰지 않는다)
     */
    step (forcedIn) {
        const p = this.p;
        const n = this.n;
        const v = this.v;
        const g = this.g;
        const nr = this.nr;
        const last = this.last;
        const rfc = this.rfc;
        const k = this.k;
        const v0 = p.v0;
        const eM = p.eM;
        const eS = p.eS;
        const kGV = p.kGV;
        const vTh = p.vTh;
        let nFired = 0;
        let fired = this._firedBuf;
        if (!fired || fired.length < n) fired = this._firedBuf = new Int32Array(n);
        // (a) 적분 + (b) 문턱 — 번호 오름차순이라 fired 도 오름차순
        for (let i = 0; i < n; i++) {
            if (k - last[i] >= rfc[i]) {
                nr[i] = 1;
                const vi = v0 + (v[i] - v0) * eM + g[i] * kGV;
                v[i] = vi;
                g[i] = g[i] * eS;
                if (vi > vTh) fired[nFired++] = i;
            } else {
                nr[i] = 0;
            }
        }
        // (c) 시냅스 슬롯: delaySteps 전에 발화한 것이 지금 도착
        const ringLen = this.ring.length;
        const arriving = p.delaySteps ? this.ring[(k + 1) % ringLen] : fired.subarray(0, nFired);
        const rowptr = this.rowptr;
        const col = this.col;
        const wv = this.wv;
        const silenced = this.silenced;
        for (let a = 0; a < arriving.length; a++) {
            const s = arriving[a];
            if (silenced[s]) continue;
            const end = rowptr[s + 1];
            for (let e = rowptr[s]; e < end; e++) {
                const t = col[e];
                if (nr[t]) g[t] += wv[e];
            }
        }
        if (forcedIn) {
            for (let j = 0; j < forcedIn.length; j++) {
                const t = forcedIn[j];
                if (nr[t]) v[t] += p.wIn;
            }
        } else {
            const rand = this.rand;
            for (let q = 0; q < this.inputs.length; q++) {
                const it = this.inputs[q];
                const idx = it.idx;
                const ps = it.pStep;
                for (let j = 0; j < idx.length; j++) {
                    if (rand() < ps) {
                        const t = idx[j];
                        if (nr[t]) v[t] += p.wIn;
                    }
                }
            }
        }
        this.ring[k % ringLen] = fired.slice(0, nFired);
        // (d) 리셋
        const sc = this.spikeCount;
        for (let a = 0; a < nFired; a++) {
            const i = fired[a];
            last[i] = k;
            v[i] = p.vReset;
            g[i] = 0;
            if (!silenced[i]) sc[i]++;
            if (this.onSpike) this.onSpike(i, k);
        }
        this.k = k + 1;
        return nFired;
    }

    /**
     * 집단의 누적 발화 수를 읽고 비운다.
     * @param {Int32Array} idx 집단의 뉴런 번호
     * @returns {number} 발화 수 합
     */
    drainCount (idx) {
        let c = 0;
        const sc = this.spikeCount;
        for (let j = 0; j < idx.length; j++) {
            c += sc[idx[j]];
            sc[idx[j]] = 0;
        }
        return c;
    }
}

/**
 * 출력 디코더 — 집단 발화율을 평활하고 이중 문턱으로 켜짐·꺼짐을 판정한다.
 * 소집단(뉴런 1~2개)은 50ms 창에 스파이크가 1~3개라 그대로 쓰면 덜컹인다.
 */
class RateDecoder {
    /**
     * @param {number} nNeurons 집단의 뉴런 수
     * @param {number} smoothMs 지수 이동 평균 시간상수
     */
    constructor (nNeurons, smoothMs) {
        this.nNeurons = Math.max(1, nNeurons);
        this.smoothMs = smoothMs;
        this.rateHz = 0;
    }
    /**
     * @param {number} spikes 지난 구간의 집단 발화 수 합
     * @param {number} spanMs 구간 길이(시뮬레이션 ms)
     * @returns {number} 평활된 발화율(Hz, 뉴런당)
     */
    update (spikes, spanMs) {
        if (spanMs <= 0) return this.rateHz;
        const inst = spikes / this.nNeurons / (spanMs / 1000);
        const a = 1 - Math.exp(-spanMs / this.smoothMs);
        this.rateHz += (inst - this.rateHz) * a;
        return this.rateHz;
    }
    reset () {
        this.rateHz = 0;
    }
}

/**
 * 묶음 파일(.fbz 를 gzip 해제한 바이트)을 신경망으로 푼다.
 * 형식: 'FBZ1' | uint32 머리말 길이 | 머리말 JSON(UTF-8, 4바이트 정렬까지 공백 채움) | 본문
 * 머리말: {n, nnz, params, sections: [{name, offset, length}]} — offset 은 본문 시작 기준
 * 본문 구획: gid(Uint32 × n, 전역 번호) · rowlen(Uint32 × n) · col(행 안 차분의 LEB128) · w8(Int8 × nnz, -128 = 넘침표 참조) · wov(Int16 × 넘침 수)
 * @param {ArrayBuffer} buf 압축을 푼 바이트
 * @returns {{n: number, nnz: number, gid: Uint32Array, rowptr: Uint32Array, col: Uint32Array, wv: Float64Array, params: object}} 신경망
 */
const decodePack = function (buf) {
    const dv = new DataView(buf);
    const magic = String.fromCharCode(dv.getUint8(0), dv.getUint8(1), dv.getUint8(2), dv.getUint8(3));
    if (magic !== 'FBZ1') throw new Error('flybrain: bad pack magic');
    const hlen = dv.getUint32(4, true);
    const hbytes = new Uint8Array(buf, 8, hlen);
    let hjson = '';
    for (let i = 0; i < hbytes.length; i++) hjson += String.fromCharCode(hbytes[i]);
    const head = JSON.parse(hjson);                                   // 머리말은 ASCII 만 쓴다
    const base = 8 + hlen;
    const sec = {};
    for (const s of head.sections) sec[s.name] = s;
    const n = head.n;
    const nnz = head.nnz;
    const gid = new Uint32Array(buf.slice(base + sec.gid.offset, base + sec.gid.offset + sec.gid.length));
    const rowlen = new Uint32Array(buf.slice(base + sec.rowlen.offset, base + sec.rowlen.offset + sec.rowlen.length));
    const colBytes = new Uint8Array(buf, base + sec.col.offset, sec.col.length);
    const w8 = new Int8Array(buf, base + sec.w8.offset, sec.w8.length);
    const wov = new Int16Array(buf.slice(base + sec.wov.offset, base + sec.wov.offset + sec.wov.length));
    const rowptr = new Uint32Array(n + 1);
    for (let i = 0; i < n; i++) rowptr[i + 1] = rowptr[i] + rowlen[i];
    if (rowptr[n] !== nnz) throw new Error('flybrain: pack row lengths do not match nnz');
    const col = new Uint32Array(nnz);
    const wv = new Float64Array(nnz);
    const wSyn = head.params.wSyn;
    let bp = 0;
    let ov = 0;
    for (let i = 0; i < n; i++) {
        let prev = 0;
        for (let e = rowptr[i]; e < rowptr[i + 1]; e++) {
            let val = 0;
            let shift = 0;
            let b;
            do {
                b = colBytes[bp++];
                val |= (b & 0x7F) << shift;
                shift += 7;
            } while (b & 0x80);
            prev += val;
            col[e] = prev;
            const w = w8[e] === -128 ? wov[ov++] : w8[e];
            wv[e] = w * wSyn;
        }
    }
    if (bp !== colBytes.length || ov !== wov.length) throw new Error('flybrain: pack body length mismatch');
    return {n, nnz, gid, rowptr, col, wv, params: head.params};
};

module.exports = {LifCore, RateDecoder, decodePack, mulberry32};
