/**
 * flybrain-worker-entry.js — 초파리 뇌 실험실(flybrain) 계산 워커.
 *
 * webpack classic 엔트리(vision-worker 선례를 그대로 따른다 — 브리프 03). 모듈 워커로 바꾸지 말 것.
 * 계산 자체는 lif-core.js(LifCore·RateDecoder) 가 하고, 이 파일은 메시지 처리·계속 돌리기 루프·
 * 디코더 호출 순서·세대(epoch) 관리만 맡는다.
 *
 * 프로토콜(계약서 §4 — 바꾸지 말 것):
 *   {seq, op:'load', model, base}      → {seq, ok, epoch, meta} 또는 {seq, ok:false, why}
 *                                          진행 중 {ev:'progress', loaded, total}
 *   {seq, op:'run', on}                → {seq, ok, epoch} 또는 {seq, ok:false, why:'not-loaded'}
 *   {op:'input', key, value}           → 응답 없음(값은 0~100 로 자른다)
 *   {op:'clearInputs'}                 → 응답 없음
 *   {op:'silence', group, on}          → 응답 없음. group:'all', on:false = 전부 다시 켜기
 *   {seq, op:'reset', scope, seed}     → {seq, ok, epoch}
 *   {seq, op:'stop'}                   → {seq, ok, epoch}
 *   {op:'dispose'}                     → 응답 없음
 *   워커가 스스로 보내는 것(seq 없음):
 *     {ev:'progress', loaded, total}
 *     {ev:'out', epoch, simTimeMs, outputs, on, rates, speed, cpuMs, cpuMsDelta, silenced}
 *
 * ▣ 세대(epoch) — load·run·reset·stop 을 **성공적으로** 처리할 때마다 1 올려 응답에 싣는다.
 *   메인은 응답의 epoch 보다 작은 epoch 의 out 을 버리므로, 실패한 요청(모델 미적재 등)에서는
 *   올리지 않는다(아무 상태도 안 바뀌었으므로).
 * ▣ stop 뒤, 그리고 run 을 끌 때(on:false) — 그 순간의 새 epoch 를 실은 전부-0 out 을 한 번 보낸다.
 *   메인 캐시가 "마지막 out 이 오래됐으면 0" 규칙(§5)을 쓰기 전에 즉시 0으로 만들어 준다.
 * ▣ 계속 돌리기 루프는 실제 타이머를 쓰지 않고 세대 토큰(this._loopGen)으로 스스로를 무효화한다 —
 *   주입되는 것이 setTimeoutImpl 뿐이고 대응하는 clearTimeout 이 없기 때문(생성자 설명 참조).
 * ▣★디코더 이중 드레인 금지 — index.groups 는 서로 겹치지 않는 해부학적 집단이라 "실험 집단"(패널용)
 *   드레인을 전부 다 하고 나면, 출력이 참조하는 집단(예: MN9·aDN)은 **이미 드레인된 값**이다.
 *   출력의 idxList 를 또 drainCount 하면 스파이크가 사라진 뒤라 0만 나온다(실측: reflex 묶음은
 *   MN9·aDN 이 패널 집단이자 동시에 출력의 유일한 집단이라 이 함정이 실제로 걸린다).
 *   그래서 출력 세기는 **이미 계산한 집단별 카운트를 index.outputs[key].groups 로 다시 모아서** 낸다
 *   (below _decodeOnce). idxList/n 은 계약서가 요구하는 모양을 맞추려고 loader 가 여전히 만들어 주지만,
 *   이 파일의 디코드 루프는 그걸 다시 drainCount 하지 않는다.
 * ▣ 부호형 출력(kind:'signed', 2단계) — groups(양) 와 neg(음) 두 집단을 각각 독립된 RateDecoder 로
 *   추적한다. 참조 방식(실험 집단 슬롯 재사용/직접 drain)은 양쪽 다 위 이중 드레인 금지 규칙을 그대로
 *   따른다. 세기 = clamp((양 - 음) / fullHz * 100, -100, 100), 켜짐/꺼짐 이력은 세기의 절댓값으로 돈다.
 *   neg 가 없는(세기형) 출력도 neg 디코더는 만들어 두되 참조가 없어 항상 0을 낸다 — 분기를 줄인다.
 */
'use strict';

const {LifCore, RateDecoder} = require('./lif-core');

const TICK_BUDGET_MS = 8;          // 한 tick 에서 스텝 계산에 쓰는 벽시계 상한
const BACKLOG_CAP_MS = 100;        // 밀린 시뮬 시간의 상한(넘으면 버린다)
const OUT_INTERVAL_MS = 40;        // out 이벤트 최소 간격(벽시계)
const IDLE_STEPS = 3000;           // 이만큼 무발화면 자극 없을 때 루프를 쉰다
const GROUP_SMOOTH_MS = 150;       // 패널(실험 집단) 표시용 디코더 시정수 — 출력 정의의 값과 통일
const LOAD_DEADLINE_MS = 45000;    // 워커 쪽 전체 적재 마감(W5) — 메인의 60초 타임아웃보다 항상 먼저 답한다
// neg 참조가 없는(세기형) 출력의 idxList 대역 — _decodeOnce 가 매 호출마다 `[]` 를 새로 만들지 않도록
// 미리 하나만 만들어 공유한다(절대 변형하지 않는다, W12 규칙).
const EMPTY_IDX_LIST = [];

/**
 * flybrain 워커의 계산·상태 core. 워커 전역과 분리돼 있어 node 단위 시험이 바로 돌릴 수 있다.
 */
class FlyBrainWorkerCore {
    /**
     * @param {object} deps
     * @param {function(object): void} deps.post 메인으로 메시지를 보낸다(seq 응답이든 ev 이벤트든)
     * @param {function(): number} deps.now 워커 자기 시계(ms, 단조 증가 가정)
     * @param {function(function(): void, number): *} deps.setTimeoutImpl setTimeout 과 같은 모양.
     *   대응하는 clearTimeout 은 주입받지 않는다 — 예약된 tick 을 무효화할 땐 this._loopGen 을 올려서
     *   tick 자신이 "내 세대가 아니면 아무 것도 안 하고 끝난다"로 스스로 멈추게 한다.
     * @param {object} deps.loader loader.js 모듈(또는 시험용 대역) — loadModel({base, model, onProgress}) 를 가진다
     */
    constructor (deps) {
        this._post = deps.post;
        this._now = deps.now;
        this._setTimeoutImpl = deps.setTimeoutImpl;
        this._loader = deps.loader;

        this._epoch = 0;
        this._lif = null;
        this._index = null;
        this._meta = null;
        this._loadToken = 0;          // 겹친 load 요청 중 낡은 쪽을 걸러낸다(W4)

        this._groups = {};            // key -> Int32Array(묶음 안 번호)
        this._inputDefs = {};         // key -> {idx, maxRateHz, parts:[{idx, maxRateHz}, ...]}
        this._outputDefs = {};        // key -> {idxList, n, fullHz, on, off, smoothMs, kind, negIdxList, negN}
        this._outputGroupKeys = {};   // 출력 key -> [그 출력이 참조하는 집단 key...] (원본 색인에서 그대로)
        this._outputNegGroupKeys = {}; // 출력 key -> [neg(음) 집단 key...] (부호형만 뜻이 있다, 원본 색인 그대로)

        this._groupDecoders = {};     // key -> RateDecoder(패널용)
        this._outputDecoders = {};    // key -> RateDecoder(출력 세기용, 부호형은 양(pos)쪽)
        this._outputNegDecoders = {}; // key -> RateDecoder(부호형 출력의 음(neg)쪽 — 세기형은 항상 0)
        this._outputOn = {};          // key -> boolean(이중 문턱 상태, 절댓값 기준)

        this._silencedGroups = new Set();
        this._inputValues = {};       // key -> 0~100

        this._running = false;
        this._sleeping = true;
        this._loopGen = 0;

        this._lastAnySpikeK = -Infinity;
        this._lastOutWall = -Infinity;
        this._lastTickWall = 0;
        this._pendingSimMs = 0;
        this._decodeAccumMs = 0;

        this._winWallStart = 0;
        this._winSimStart = 0;
        this._winCpuMs = 0;
        this._speed = 0;
        this._cpuMs = 0;
        this._cpuMsSinceOut = 0;      // 직전 out 이후 스텝 계산에 쓴 벽시계 ms 누산 — out 마다 실어 보내고 0으로(W6)
    }

    /**
     * 메인에서 온 메시지 하나를 처리한다. 동기 처리 중 던진 예외는 seq 가 있으면 실패 응답으로 바꾼다
     * (seq 가 없는 fire-and-forget 메시지는 조용히 삼킨다 — 원래도 응답이 없는 종류들이다).
     * @param {object} m {seq?, op, ...}
     */
    handleMessage (m) {
        m = m || {};
        try {
            switch (m.op) {
            case 'load':
                this._onLoad(m);
                return;
            case 'run':
                this._onRun(m);
                return;
            case 'input':
                this._onInput(m);
                return;
            case 'clearInputs':
                this._onClearInputs();
                return;
            case 'silence':
                this._onSilence(m);
                return;
            case 'reset':
                this._onReset(m);
                return;
            case 'stop':
                this._onStop(m);
                return;
            case 'dispose':
                this._onDispose();
                return;
            default:
                return;
            }
        } catch (e) {
            if (typeof m.seq !== 'undefined') {
                this._post({seq: m.seq, ok: false, why: 'internal-error', detail: (e && e.message) || String(e)});
            }
        }
    }

    /**
     * @param {object} m {seq, model, base}
     * ▣ 적재 토큰(W4) — 겹친 load 요청 중 가장 나중에 시작된 것만 설치된다. `await` 뒤에 토큰이
     *   더 이상 최신이 아니면(다른 load 가 그 사이 시작됐으면) 설치를 건너뛰고 superseded 로 끝낸다.
     *   onProgress 도 같은 토큰 검사를 거쳐 낡은 줄기의 진행률이 새지 않게 막는다.
     */
    async _onLoad (m) {
        const seq = m.seq;
        const token = ++this._loadToken;
        try {
            // 모델을 바꾸는 동안 이전 루프가 새 상태를 밟지 않게 먼저 멈춘다.
            this._loopGen += 1;
            this._running = false;
            this._sleeping = true;

            let result;
            try {
                result = await this._loader.loadModel({
                    base: m.base,
                    model: m.model,
                    deadlineMs: LOAD_DEADLINE_MS,
                    onProgress: (loaded, total) => {
                        if (token !== this._loadToken) return; // 낡은 줄기 — 진행률을 흘리지 않는다(W4)
                        this._post({ev: 'progress', loaded, total});
                    }
                });
            } catch (e) {
                result = {ok: false, why: 'internal-error', detail: (e && e.message) || String(e)};
            }

            if (token !== this._loadToken) {
                // 기다리는 동안 더 최신 load 가 시작됐다 — 이쪽은 설치하지 않고 그대로 포기한다(W4).
                this._post({seq, ok: false, why: 'superseded'});
                return;
            }

            if (!result || !result.ok) {
                // 계약서의 응답 모양은 {ok:false, why} 뿐이지만, detail 은 있으면 얹는다(진단용 — 없어도
                // 메인 쪽 판정에는 영향 없다. why 만 보고 판단하게 돼 있다).
                const resp = {seq, ok: false, why: (result && result.why) || 'load-failed'};
                if (result && typeof result.detail !== 'undefined') resp.detail = result.detail;
                this._post(resp);
                return;
            }

            this._installModel(m.model, result);
            this._epoch += 1;
            this._post({seq, ok: true, epoch: this._epoch, meta: this._meta});
        } catch (e) {
            this._post({seq, ok: false, why: 'internal-error', detail: (e && e.message) || String(e)});
        }
    }

    /** loadModel 성공 결과로 워커 내부 상태(신경망·디코더·메타)를 새로 만든다. */
    _installModel (model, result) {
        this._lif = new LifCore(result.net);
        this._index = result.index;

        this._groups = result.groups;
        this._inputDefs = result.inputs;
        this._outputDefs = result.outputs;

        this._outputGroupKeys = {};
        this._outputNegGroupKeys = {};
        const outDefsRaw = (result.index && result.index.outputs) || {};
        for (const key of Object.keys(this._outputDefs)) {
            const raw = outDefsRaw[key];
            this._outputGroupKeys[key] = (raw && raw.groups) || [];
            this._outputNegGroupKeys[key] = (raw && raw.neg) || [];
        }

        this._groupDecoders = {};
        for (const key of Object.keys(this._groups)) {
            this._groupDecoders[key] = new RateDecoder(this._groups[key].length, GROUP_SMOOTH_MS);
        }

        this._outputDecoders = {};
        this._outputNegDecoders = {};
        this._outputOn = {};
        for (const key of Object.keys(this._outputDefs)) {
            const def = this._outputDefs[key];
            this._outputDecoders[key] = new RateDecoder(def.n, def.smoothMs);
            // def.negN 은 loader 를 거치지 않은 옛 시험 픽스처엔 없을 수 있다 — 그때는 0(=참조 없음)으로.
            this._outputNegDecoders[key] = new RateDecoder(def.negN || 0, def.smoothMs);
            this._outputOn[key] = false;
        }

        // ★W12 — _decodeOnce 가 매 시뮬 1ms 마다 새 객체·배열을 만들지 않도록 여기서 한 번만 준비한다.
        // _groupCountBuf[i] = _groupKeys[i] 집단의 이번 구간 발화 수(드레인 값), _groupIdxOf 는 그 자리 찾기용.
        this._groupKeys = Object.keys(this._groups);
        this._outputKeys = Object.keys(this._outputDefs);
        this._groupCountBuf = new Float64Array(this._groupKeys.length);
        this._groupIdxOf = {};
        this._groupKeys.forEach((k, i) => { this._groupIdxOf[k] = i; });
        // 출력마다 "참조하는 집단을 어디서 가져올지"를 미리 정해 둔다 — 원래 _decodeOnce 의 판정
        // (실험 집단 목록에 있으면 그 카운트를 재사용, 없지만 색인엔 있으면 직접 drain, 둘 다 아니면
        // 건너뜀 — 파일 머리 설명의 이중 드레인 금지 규칙)을 그대로 옮긴 것뿐이라 동작은 그대로다.
        // neg 쪽도 완전히 같은 방식으로 미리 정해 둔다. 세기형 출력은 gkeys 가 항상 비어 useIdxList 로
        // 떨어지는데, 그 대역을 매 호출마다 새로 만들지 않도록 EMPTY_IDX_LIST(모듈 공유 빈 배열, 절대
        // 변형 금지)로 고정해 둔다 — def.negIdxList 가 아예 없는 옛 시험 픽스처도 이 경로로 안전하다.
        this._outputGroupRefs = {};
        this._outputNegGroupRefs = {};
        for (const key of this._outputKeys) {
            const def = this._outputDefs[key];

            const gkeys = this._outputGroupKeys[key] || [];
            const refs = [];
            for (const g of gkeys) {
                if (Object.prototype.hasOwnProperty.call(this._groupIdxOf, g)) {
                    refs.push({slot: this._groupIdxOf[g]});
                } else if (this._groups[g]) {
                    refs.push({direct: this._groups[g]});
                }
                // 그 외(전역 색인에도 없는 집단)는 원래 코드처럼 조용히 건너뛴다.
            }
            this._outputGroupRefs[key] = {refs, useIdxList: gkeys.length === 0};

            const negGkeys = this._outputNegGroupKeys[key] || [];
            const negRefs = [];
            for (const g of negGkeys) {
                if (Object.prototype.hasOwnProperty.call(this._groupIdxOf, g)) {
                    negRefs.push({slot: this._groupIdxOf[g]});
                } else if (this._groups[g]) {
                    negRefs.push({direct: this._groups[g]});
                }
            }
            this._outputNegGroupRefs[key] = {
                refs: negRefs,
                useIdxList: negGkeys.length === 0,
                idxList: (def && def.negIdxList) || EMPTY_IDX_LIST,
                // 심사 D1 — neg 참조가 아예 없는(세기형, 절대다수) 출력은 _decodeOnce 의 neg 계산
                // 전체(빈 배열 순회·디코더 update)를 건너뛴다. negN 개 뉴런이 없으면 drain 결과는
                // 구조적으로 항상 0 이라, 건너뛰어도 값은 그대로다(0 에서 시작해 0 만 넣으면 0 그대로).
                hasNeg: !!(def && def.negN)
            };
        }

        this._silencedGroups.clear();
        this._inputValues = {};

        this._running = false;
        this._sleeping = true;
        this._loopGen += 1;

        this._lastAnySpikeK = -Infinity;
        this._lastOutWall = -Infinity;
        this._pendingSimMs = 0;
        this._decodeAccumMs = 0;

        this._winWallStart = this._now();
        this._winSimStart = 0;
        this._winCpuMs = 0;
        this._speed = 0;
        this._cpuMs = 0;
        this._cpuMsSinceOut = 0;

        this._meta = {
            model,
            version: (result.index && result.index.id) || null,
            n: this._lif.n,
            nnz: result.net.nnz,
            inputs: Object.keys(this._inputDefs),
            outputs: Object.keys(this._outputDefs),
            groups: Object.keys(this._groups),
            source: (result.index && result.index.source) || null,
            insecure: !!result.insecure
        };
    }

    /**
     * 출력·실험 집단 디코더 상태를 전부 비운다 — stop·run:false·reset·잠들기 네 경로가 같이 쓴다(W2·W7).
     * 여기서 안 비우면 재개했을 때 정지 전의 스무딩된 값이 살아남아 첫 out 이 곧바로 되살아난다.
     */
    _zeroDecoders () {
        for (const k of Object.keys(this._groupDecoders)) this._groupDecoders[k].reset();
        for (const k of Object.keys(this._outputDecoders)) {
            this._outputDecoders[k].reset();
            this._outputOn[k] = false;
        }
        for (const k of Object.keys(this._outputNegDecoders)) this._outputNegDecoders[k].reset();
        this._decodeAccumMs = 0;
    }

    /** @param {object} m {seq, on} */
    _onRun (m) {
        const seq = m.seq;
        if (!this._lif) {
            this._post({seq, ok: false, why: 'not-loaded'});
            return;
        }
        const on = !!m.on;
        this._running = on;
        this._epoch += 1;
        const epoch = this._epoch;
        this._post({seq, ok: true, epoch});

        if (on) {
            this._sleeping = false;
            this._pendingSimMs = 0;
            this._lastTickWall = this._now();
            this._winWallStart = this._lastTickWall;
            this._winSimStart = this._simTimeMs();
            this._winCpuMs = 0;
            this._loopGen += 1;
            this._scheduleTick();
        } else {
            this._sleeping = true;
            this._loopGen += 1; // 예약돼 있던 tick 을 무효화
            this._zeroDecoders(); // W2 — 꺼진 채 있다가 다시 켜져도 정지 전 출력이 되살아나지 않게
            this._emitZeroOut(epoch);
        }
    }

    /** @param {object} m {seq} */
    _onStop (m) {
        const seq = m.seq;
        this._epoch += 1;
        const epoch = this._epoch;

        this._running = false;
        this._sleeping = true;
        this._loopGen += 1;

        if (this._lif) {
            this._inputValues = {};
            this._lif.setInputs([]);
            this._zeroDecoders(); // W2
        }

        this._post({seq, ok: true, epoch});
        if (this._lif) this._emitZeroOut(epoch);
    }

    /** @param {object} m {seq, scope, seed} */
    _onReset (m) {
        const seq = m.seq;
        this._epoch += 1;
        const epoch = this._epoch;

        if (this._lif) {
            const seed = (typeof m.seed === 'number') ? m.seed : 1;
            this._lif.reset(seed);

            this._inputValues = {};
            this._lif.setInputs([]);

            this._zeroDecoders(); // W2 — 이전엔 여기 있던 코드가 그대로 함수로 빠졌다(세 경로가 갈라지지 않게)

            this._lastAnySpikeK = -Infinity;
            this._pendingSimMs = 0;

            if (m.scope === 'all') {
                this._lif.silenced.fill(0);
                this._silencedGroups.clear();
            }

            if (this._running) {
                this._sleeping = false;
                this._lastTickWall = this._now();
                this._winWallStart = this._lastTickWall;
                this._winSimStart = 0;
                this._winCpuMs = 0;
                this._loopGen += 1;
                this._scheduleTick();
            }
        }

        this._post({seq, ok: true, epoch});
    }

    _onDispose () {
        this._loopGen += 1;
        this._running = false;
        this._sleeping = true;
        this._lif = null;
        this._index = null;
        this._meta = null;
    }

    /** @param {object} m {key, value} */
    _onInput (m) {
        if (!this._lif) return;
        if (!this._inputDefs[m.key]) return; // 이 묶음에 없는 감각 - 무시(루프가 잠들 수 있게, W11)
        let value = Number(m.value);
        if (!isFinite(value)) value = 0;
        if (value < 0) value = 0;
        if (value > 100) value = 100;
        this._inputValues[m.key] = value;
        this._applyInputs();
        if (value > 0 && this._running && this._sleeping) this._wake();
    }

    _onClearInputs () {
        if (!this._lif) return;
        this._inputValues = {};
        this._lif.setInputs([]);
    }

    /** @param {object} m {group, on} */
    _onSilence (m) {
        if (!this._lif) return;
        const on = !!m.on;
        if (m.group === 'all' && !on) {
            this._lif.silenced.fill(0);
            this._silencedGroups.clear();
            return;
        }
        const idx = this._groups[m.group];
        if (!idx) return;
        for (let j = 0; j < idx.length; j++) this._lif.silenced[idx[j]] = on ? 1 : 0;
        if (on) this._silencedGroups.add(m.group);
        else this._silencedGroups.delete(m.group);
    }

    /**
     * this._inputValues(0~100) 을 LifCore.setInputs 가 받는 {idx, rateHz} 목록으로 다시 만든다.
     * 입력 하나가 parts 여러 개(서로 다른 집단·서로 다른 maxRateHz)를 가질 수 있다(2단계) — parts 가
     * 없는 옛 정의(1판, 또는 loader 를 거치지 않는 시험 픽스처)는 자기 자신을 parts 원소 1개로 다룬다.
     * (핫루프인 _decodeOnce 와 달리 이 함수는 입력 블록이 호출될 때만 도니 새 배열 생성이 문제되지 않는다.)
     */
    _applyInputs () {
        const list = [];
        for (const key of Object.keys(this._inputValues)) {
            const v = this._inputValues[key];
            if (v > 0) {
                const def = this._inputDefs[key];
                if (!def) continue;
                const parts = def.parts || [{idx: def.idx, maxRateHz: def.maxRateHz}];
                for (let i = 0; i < parts.length; i++) {
                    const part = parts[i];
                    list.push({idx: part.idx, rateHz: (v / 100) * part.maxRateHz});
                }
            }
        }
        this._lif.setInputs(list);
    }

    _hasActiveInput () {
        for (const key of Object.keys(this._inputValues)) {
            // 정의된 키만 "활성"으로 친다(W11) — _onInput 이 이미 걸러내지만, 한 겹 더 방어한다.
            if (this._inputValues[key] > 0 && this._inputDefs[key]) return true;
        }
        return false;
    }

    _simTimeMs () {
        return this._lif ? this._lif.k * this._lif.p.dtMs : 0;
    }

    /** 자는 중이던 루프를 깨운다(밀린 시간을 시뮬로 되갚지 않도록 기준시각을 지금으로 다시 잡는다). */
    _wake () {
        this._sleeping = false;
        this._pendingSimMs = 0;
        this._lastTickWall = this._now();
        this._loopGen += 1;
        this._scheduleTick();
    }

    _scheduleTick () {
        const gen = this._loopGen;
        this._setTimeoutImpl(() => {
            if (gen !== this._loopGen) return; // 그 사이 stop·reset·load·run:false 로 무효화됨
            this._tick(gen);
        }, 0);
    }

    /**
     * 한 tick — 벽시계로 흘렀어야 할 시뮬 시간만큼(최대 100ms 분량) 스텝을 돌리되 벽시계 8ms 를 넘기지 않는다.
     * @param {number} gen 이 tick 을 예약할 때의 세대(다시 확인 — 콜백 사이에 바뀌었을 수 있다)
     */
    _tick (gen) {
        if (gen !== this._loopGen || !this._running || !this._lif) return;

        const wallNow = this._now();
        const delta = Math.max(0, wallNow - this._lastTickWall);
        this._lastTickWall = wallNow;

        const idle = !this._hasActiveInput() && (this._lif.k - this._lastAnySpikeK) >= IDLE_STEPS;
        if (idle) {
            this._sleeping = true;
            // W7 — 잠들기 직전 상태를 0으로 확정하고 마지막 out 을 한 번 보낸다. 안 보내면 활동 창이
            // 0 이 아닌 막대로 얼어붙고, 메인의 whenOutput 가장자리 상태도 거짓 켜짐인 채로 남는다.
            // _sleeping 이 참일 때는 이 tick 자체가 다시 예약되지 않으므로 두 번 보내지 않는다.
            this._zeroDecoders();
            this._emitZeroOut(this._epoch);
            this._lastOutWall = wallNow;
            return; // 다음 input 이나 run 이 깨울 때까지 다시 예약하지 않는다
        }

        this._pendingSimMs = Math.min(this._pendingSimMs + delta, BACKLOG_CAP_MS);

        const dtMs = this._lif.p.dtMs;
        const budgetStart = wallNow;
        while (this._pendingSimMs >= dtMs && (this._now() - budgetStart) < TICK_BUDGET_MS) {
            const nFired = this._lif.step();
            if (nFired > 0) this._lastAnySpikeK = this._lif.k - 1;
            this._pendingSimMs -= dtMs;
            this._decodeAccumMs += dtMs;
            if (this._decodeAccumMs >= 1) {
                this._decodeAccumMs -= 1;
                this._decodeOnce();
            }
        }
        const cpuMs = this._now() - budgetStart;
        this._winCpuMs += cpuMs;
        this._cpuMsSinceOut += cpuMs; // W6 — 다음 out 에 cpuMsDelta 로 실어 보낼 몫

        const wallSinceWin = wallNow - this._winWallStart;
        if (wallSinceWin >= 1000) {
            const simNow = this._simTimeMs();
            this._speed = wallSinceWin > 0 ? (simNow - this._winSimStart) / wallSinceWin : 0;
            this._cpuMs = this._winCpuMs;
            this._winWallStart = wallNow;
            this._winSimStart = simNow;
            this._winCpuMs = 0;
        }

        if ((wallNow - this._lastOutWall) >= OUT_INTERVAL_MS) {
            this._emitOut();
            this._lastOutWall = wallNow;
        }

        this._scheduleTick();
    }

    /**
     * 시뮬 1ms 마다 한 번 — 집단별(패널용) drainCount 를 전부 먼저 하고, 출력 세기는 그 결과를 다시 모아 낸다.
     * ★같은 뉴런을 두 번 drainCount 하면 두 번째는 0만 나온다(위 파일 머리 설명) — 그래서 출력은
     *   idxList 를 다시 drain 하지 않고 groupCounts(=_groupCountBuf)를 재사용한다. 출력이 참조하는
     *   집단이 "실험 집단" 목록에 없는 예외적인 경우에만 그 자리에서 직접 drain 한다(겹치지 않으므로 안전).
     *   부호형 출력의 neg(음) 집단도 같은 규칙으로 얻는다 — pos·neg 는 서로 다른 집단이라 겹치지 않는다.
     * ★W12 — 초당 최대 1,000회 불리므로 이 함수 안에서는 새 객체·배열을 만들지 않는다. 키 배열·
     *   카운트 버퍼·출력별 참조 목록은 전부 _installModel 이 한 번만 만들어 둔 것을 재사용한다.
     */
    _decodeOnce () {
        const groupKeys = this._groupKeys;
        const groupCountBuf = this._groupCountBuf;
        for (let i = 0; i < groupKeys.length; i++) {
            const key = groupKeys[i];
            const c = this._lif.drainCount(this._groups[key]);
            groupCountBuf[i] = c;
            this._groupDecoders[key].update(c, 1);
        }

        const outputKeys = this._outputKeys;
        for (let oi = 0; oi < outputKeys.length; oi++) {
            const key = outputKeys[oi];
            const def = this._outputDefs[key];

            const {refs, useIdxList} = this._outputGroupRefs[key];
            let c = 0;
            if (useIdxList) {
                // 원본 색인에 groups 가 없는 예외적인 상황 — idxList 로 대신한다(이땐 겹칠 일이 없다).
                for (const arr of def.idxList) c += this._lif.drainCount(arr);
            } else {
                for (let ri = 0; ri < refs.length; ri++) {
                    const r = refs[ri];
                    c += (typeof r.slot === 'number') ? groupCountBuf[r.slot] : this._lif.drainCount(r.direct);
                }
            }
            const posRate = this._outputDecoders[key].update(c, 1);

            // 심사 D1 — neg 참조가 없는(세기형, 절대다수) 출력은 이 블록 전체를 건너뛴다. 초당 최대
            // 1,000번 도는 함수라 빈 배열 순회(이터레이터 생성)·불필요한 디코더 update 가 누적되면 아깝다.
            const negGroupRef = this._outputNegGroupRefs[key];
            let negRate = 0;
            if (negGroupRef.hasNeg) {
                const {refs: negRefs, useIdxList: negUseIdxList, idxList: negIdxListCached} = negGroupRef;
                let negC = 0;
                if (negUseIdxList) {
                    for (const arr of negIdxListCached) negC += this._lif.drainCount(arr);
                } else {
                    for (let ri = 0; ri < negRefs.length; ri++) {
                        const r = negRefs[ri];
                        negC += (typeof r.slot === 'number') ? groupCountBuf[r.slot] : this._lif.drainCount(r.direct);
                    }
                }
                negRate = this._outputNegDecoders[key].update(negC, 1);
            }

            let strength;
            if (def.kind === 'signed') {
                const signedRate = posRate - negRate;
                strength = Math.max(-100, Math.min(100, (signedRate / def.fullHz) * 100));
            } else {
                strength = Math.min(100, (posRate / def.fullHz) * 100);
            }
            const absStrength = Math.abs(strength);
            const wasOn = this._outputOn[key];
            if (!wasOn && absStrength >= def.on) this._outputOn[key] = true;
            else if (wasOn && absStrength <= def.off) this._outputOn[key] = false;
        }
    }

    _emitOut () {
        const outputs = {};
        const on = {};
        for (const key of Object.keys(this._outputDefs)) {
            const dec = this._outputDecoders[key];
            const def = this._outputDefs[key];
            if (def.kind === 'signed') {
                const negDec = this._outputNegDecoders[key];
                const signed = ((dec.rateHz - negDec.rateHz) / def.fullHz) * 100;
                outputs[key] = Math.max(-100, Math.min(100, signed));
            } else {
                outputs[key] = Math.min(100, (dec.rateHz / def.fullHz) * 100);
            }
            on[key] = !!this._outputOn[key];
        }
        const rates = {};
        for (const key of Object.keys(this._groupDecoders)) rates[key] = this._groupDecoders[key].rateHz;

        // W6 — cpuMsDelta = 직전 out 이후 스텝 계산에 쓴 벽시계 ms. 보낸 뒤 0으로 되돌린다(cpuMs 는 그대로 둔다).
        const cpuMsDelta = this._cpuMsSinceOut;
        this._cpuMsSinceOut = 0;

        this._post({
            ev: 'out',
            epoch: this._epoch,
            simTimeMs: this._simTimeMs(),
            outputs,
            on,
            rates,
            speed: this._speed,
            cpuMs: this._cpuMs,
            cpuMsDelta,
            silenced: Array.from(this._silencedGroups)
        });
    }

    /** stop 뒤 / run off 뒤 / 잠들기 직전에 보내는 전부-0 out(새 epoch 를 실어 메인 캐시를 즉시 비운다). */
    _emitZeroOut (epoch) {
        const outputs = {};
        const on = {};
        for (const key of Object.keys(this._outputDefs)) {
            outputs[key] = 0;
            on[key] = false;
        }
        const rates = {};
        for (const key of Object.keys(this._groupDecoders)) rates[key] = 0;

        // 여기까지 쌓인 계산 시간도 이 out 에 실어 보내고 비운다(W6) — 다음 실제 out 으로 새지 않게.
        const cpuMsDelta = this._cpuMsSinceOut;
        this._cpuMsSinceOut = 0;

        this._post({
            ev: 'out',
            epoch,
            simTimeMs: this._simTimeMs(),
            outputs,
            on,
            rates,
            speed: 0,
            cpuMs: 0,
            cpuMsDelta,
            silenced: Array.from(this._silencedGroups)
        });
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = FlyBrainWorkerCore;
}

// 진짜 워커 안에서 돌 때만 self.onmessage 를 잡는다(vision-worker-entry.js 는 이 구분이 필요 없는
// 단독 스크립트라 안 하지만, 이 파일은 node 시험이 FlyBrainWorkerCore 를 직접 가져다 쓰므로 필요하다).
if (typeof self !== 'undefined' && typeof importScripts === 'function') {
    const loader = require('./loader');
    const core = new FlyBrainWorkerCore({
        post: msg => self.postMessage(msg),
        now: () => self.performance.now(),
        setTimeoutImpl: (fn, ms) => self.setTimeout(fn, ms),
        loader
    });
    self.onmessage = e => core.handleMessage(e.data);
}
